#[derive(PartialEq, Eq, Debug)]
pub enum Bucket {
    One,
    Two,
}

/// A struct to hold your results in.
#[derive(PartialEq, Eq, Debug)]
pub struct BucketStats {
    /// The total number of "moves" it should take to reach the desired number of liters, including
    /// the first fill.
    pub moves: u8,
    /// Which bucket should end up with the desired number of liters? (Either "one" or "two")
    pub goal_bucket: Bucket,
    /// How many liters are left in the other bucket?
    pub other_bucket: u8,
}

/// Solve the bucket problem
pub fn solve(
    capacity_1: u8,
    capacity_2: u8,
    goal: u8,
    start_bucket: &Bucket,
) -> Option<BucketStats> {
    let cap1 = capacity_1 as u32;
    let cap2 = capacity_2 as u32;
    let goal = goal as u32;

    if goal > cap1 && goal > cap2 {
        return None;
    }

    let start_state: (u32, u32) = match start_bucket {
        Bucket::One => (cap1, 0),
        Bucket::Two => (0, cap2),
    };

    let forbidden: (u32, u32) = match start_bucket {
        Bucket::One => (0, cap2),
        Bucket::Two => (cap1, 0),
    };

    let mut visited = std::collections::HashSet::new();
    visited.insert(start_state);
    let mut queue: VecDeque<((u32, u32), u32)> = VecDeque::new();
    queue.push_back((start_state, 1));

    while let Some(((x, y), moves)) = queue.pop_front() {
        if x == goal {
            return Some(BucketStats {
                moves: moves as u8,
                goal_bucket: Bucket::One,
                other_bucket: y as u8,
            });
        }
        if y == goal {
            return Some(BucketStats {
                moves: moves as u8,
                goal_bucket: Bucket::Two,
                other_bucket: x as u8,
            });
        }

        let mut next_states = Vec::new();
        // fill bucket 1
        next_states.push((cap1, y));
        // fill bucket 2
        next_states.push((x, cap2));
        // empty bucket 1
        next_states.push((0, y));
        // empty bucket 2
        next_states.push((x, 0));
        // pour 1 into 2
        {
            let amount = std::cmp::min(x, cap2 - y);
            next_states.push((x - amount, y + amount));
        }
        // pour 2 into 1
        {
            let amount = std::cmp::min(y, cap1 - x);
            next_states.push((x + amount, y - amount));
        }

        for state in next_states {
            if state == forbidden {
                continue;
            }
            if visited.insert(state) {
                queue.push_back((state, moves + 1));
            }
        }
    }

    None
}
"}

